#include <iostream>
#include <vector>

int firstIndexOf(const std::vector<int>& v, int target)
{
    for (std::size_t i = 0; i < v.size(); ++i)
        if (v[i] == target) return static_cast<int>(i);
    return -1;
}

int lastIndexOf(const std::vector<int>& v, int target)
{
    for (std::size_t i = v.size(); i > 0; --i)
        if (v[i - 1] == target) return static_cast<int>(i - 1);
    return -1;
}

int main()
{
    int n{};
    if (!(std::cin >> n)) return 0;

    std::vector<int> v;
    for (int i = 0; i < n; ++i)
    {
        int x{};
        std::cin >> x;
        v.push_back(x);
    }

    int q{};
    std::cin >> q;
    for (int i = 0; i < q; ++i)
    {
        int target{};
        std::cin >> target;
        int f{ firstIndexOf(v, target) };
        if (f < 0) std::cout << target << " absent\n";
        else       std::cout << target << " first " << f
                             << " last " << lastIndexOf(v, target) << "\n";
    }

    return 0;
}

