import sys

def first_index_of(v, target):
    for i in range(len(v)):
        if v[i] == target:
            return i
    return -1

def last_index_of(v, target):
    for i in range(len(v), 0, -1):
        if v[i - 1] == target:
            return i - 1
    return -1

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    pos = 0
    n = int(data[pos]); pos += 1
    v = [int(data[pos + i]) for i in range(n)]; pos += n
    q = int(data[pos]); pos += 1
    out = []
    for _ in range(q):
        target = int(data[pos]); pos += 1
        f = first_index_of(v, target)
        if f < 0:
            out.append("%d absent" % target)
        else:
            out.append("%d first %d last %d" % (target, f, last_index_of(v, target)))
    print("\n".join(out))

main()
